let project=null,stage='program',selected='$station',tool='select',expanded=new Set(['$station']),query='',issuesOnly=false,busy=false,stopRequested=false;
let undo=[],redo=[],view=null,gesture=null,selectedEquipment=null,selectedInterface=null;
let selectedGameflowRule='';
