        if(definition)html+=`<p class="node-small">Template floor bounds ${definition.area.min}–${definition.area.max}; max aspect ${definition.shape.maxAspectRatio}; minimum fill ${definition.shape.minFillRatio}. ${definition.allowThroughTraffic?'Transit is permitted.':'Transit through this room is forbidden.'}</p>`;
