        if(node.definitionPath.split('/').length>2)html+=`<p class="node-small">Nested in ${esc(roomParentLabel(node))}. Template edits apply to every instance; the selected-count override applies to this parent.</p><div class="fields">${Object.entries({internal:'Keep inside parent complex',requireParentConnection:'Require parent connection',allowExternalEntry:'Allow entry bypassing parent'}).map(([key,label])=>`<label class="check"><input type="checkbox" data-requirement="nesting.${key}" ${definition.nesting?.[key]?'checked':''}>${label}</label>`).join('')}</div>`;
