$('design-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>32*1024*1024)throw new Error('Design files must fit within 32 MiB.');const saved=JSON.parse(await file.text());const before=snapshot(),loaded=await api('design/import',saved.project||saved);remember(before);stage=saved.stage||loaded.stage;selected=saved.selected||'$station';accept(loaded);fit();status('Opened project and rechecked its requirement tree.');}catch(error){notice(error.message,true);}finally{event.target.value='';}});
